    var picked = pickSnap(uv, snapTargets(excludePart).concat(onCurveTargets(uv, ensureSketch(E.def), origin, E.scl)), {
      scale: E.scl, cycleIndex: E.inferenceIndex, suppress: E._suppressInference,
    });
