  if (id !== E.tool) E.dynInput = null;
  if (id !== E.tool) { E.dimPick = []; E.dimSel = null; }
  E.tool = id;
  /* Arms the sheet, never disarms it: picking Select inside a sketch you are
     already drawing means "select in this sketch", not "leave it". */
