    c.moveTo(uA.x, uA.y); c.lineTo(uB.x, uB.y); c.moveTo(vA.x, vA.y); c.lineTo(vB.x, vB.y);
    c.stroke();
    c.fillStyle = "rgba(90,110,130,.85)";
    c.font = "11px sans-serif";
