    ambientColor: rig.hemi ? "#" + rig.hemi.color.getHexString() : undefined,
    ambientIntensity: rig.hemi ? rig.hemi.intensity : undefined,
    fillColor: rig.fill ? "#" + rig.fill.color.getHexString() : undefined,
